1	import { useCallback, useEffect, useRef, useState } from "react";
2	import { lookupArtistLocation } from "../../shared/geocode.js";
3	import { devLog } from "../devLog.js";
4	import { classifyPollError } from "../pollError.js";
5	import { fetchCurrentlyPlaying, pause, play, skipToNext } from "../spotify.js";
6	import { MUTED, overlayCardStyle } from "../theme.js";
7	import { UNKNOWN_LOCATION } from "../unknownLocation.js";
8	import { useLibraryArtists } from "../useLibraryArtists.js";
9	import BrowseLibraryButton from "./BrowseLibraryButton.jsx";
10	import LeafletMap from "./LeafletMap.jsx";
11	import LibraryLoadingBadge from "./LibraryLoadingBadge.jsx";
12	import NowPlayingCard from "./NowPlayingCard.jsx";
13	
14	const POLL_MS = 5_000;
15	const SCOPE_WARNING = "Log out and back in to enable Browse Library";
16	
17	// A playback failure the user can act on beats an accurate one they can't.
18	// spotify.js already distinguishes these cases; collapsing them into one
19	// string was the whole reason "nothing playing + click an artist" read as a
20	// bug rather than as "open Spotify somewhere". Only NO_ACTIVE_DEVICE survives
21	// play()'s device fallback — by then it means nothing is open ANYWHERE, which
22	// no API call can fix.
23	const CONTROL_MESSAGES = {
24	  NO_ACTIVE_DEVICE: "Open Spotify on any device, then try again",
25	  PLAYBACK_UNAVAILABLE: "Spotify Premium is required to control playback",
26	  INSUFFICIENT_SCOPE: "Log out and back in to enable playback control",
27	};
28	const CONTROL_FALLBACK = "Playback control not available";
29	
30	// Fix 1 (final whole-branch review): explore mode's flagship feature — the
31	// clustered library map — must be reachable no matter what the now-playing
32	// poll is doing. These two states used to be full-screen early returns that
33	// replaced the map entirely, which meant BrowseLibraryButton and
34	// LibraryLoadingBadge only existed once something was playing. Both status
35	// messages are now a small overlay on top of the (always-rendered) map
36	// instead. "error" gets the same treatment as "idle": every case that lands
37	// here is an unrecognized *poll* error (classifyPollError already routes
38	// TOKEN_EXPIRED to a silent refresh and RATE_LIMITED to a retry) — never a
39	// hard auth failure — and the library-resolution loop is independent of the
40	// now-playing poll, so there's no reason a flaky currently-playing request
41	// should block browsing an already-fetched library.
42	const STATUS_OVERLAY_STYLE = {
43	  position: "fixed",
44	  top: "50%",
45	  left: "50%",
46	  transform: "translate(-50%, -50%)",
47	  zIndex: 900,
48	  padding: "16px 24px",
49	  textAlign: "center",
50	  // Nothing inside this overlay is interactive (just a message), and it now
51	  // sits on top of the always-rendered map — without this it swallows
52	  // clicks on any cluster/marker underneath it in explore mode while
53	  // idle/error.
54	  pointerEvents: "none",
55	  ...overlayCardStyle,
56	};
57	
58	// Fallback location for the scope warning / a control error when there's no
59	// NowPlayingCard to host the message (see displayMessage below). Mirrors
60	// NowPlayingCard's own message-slot styling (top-right, MUTED, 12px) so it
61	// reads as the same kind of notice.
62	//
63	// `color: MUTED` must come AFTER the `...overlayCardStyle` spread —
64	// overlayCardStyle sets `color: TEXT` (white), and object spread applies in
65	// source order, so putting MUTED first was silently overridden by white.
66	const STANDALONE_MESSAGE_STYLE = {
67	  position: "fixed",
68	  top: 16,
69	  right: 16,
70	  zIndex: 1000,
71	  padding: "10px 16px",
72	  fontSize: 12,
73	  textAlign: "center",
74	  ...overlayCardStyle,
75	  color: MUTED,
76	};
77	
78	export default function MapView({ token, onTokenExpired }) {
79	  const [track, setTrack] = useState(null);
80	  const [location, setLocation] = useState(null);
81	  const [status, setStatus] = useState("loading");
82	  const [controlMessage, setControlMessage] = useState(null);
83	  const [exploreMode, setExploreMode] = useState(false);
84	  const lastArtistRef = useRef(null);
85	  const refreshingRef = useRef(false);
86	  const mountedRef = useRef(true);
87	
88	  // Runs unconditionally from app boot regardless of exploreMode, per spec —
89	  // the background resolution loop keeps the library pre-populated so
90	  // explore mode is ready by the time the user opens it.
91	  const { artists, resolvedCount, total, scopeMissing, failedCount } =
92	    useLibraryArtists(token);
93	
94	  useEffect(() => {
95	    mountedRef.current = true;
96	    return () => {
97	      mountedRef.current = false;
98	    };
99	  }, []);
100	
101	  // Surfaces a stale-scope 403 (a session authorized before `user-follow-read`
102	  // was added — see the design doc's migration note) alongside the existing
103	  // transient controlMessage, without storing it in that same state. It's a
104	  // *persistent* condition (stays true until the user re-logs-in) riding on
105	  // a channel (`controlMessage`) that `runControl` unconditionally clears on
106	  // every successful play/pause/skip/select — storing the warning there
107	  // caused it to be silently wiped out by the next unrelated successful
108	  // control action. Deriving it instead means there's no state for anything
109	  // to clobber: a transient control error still wins while it's showing
110	  // (matches existing single-message-slot UI), and the scope warning simply
111	  // reappears on its own once that transient message clears, because
112	  // `scopeMissing` itself hasn't changed.
113	  const displayMessage =
114	    controlMessage ?? (scopeMissing ? SCOPE_WARNING : null);
115	
116	  // Fetch the currently-playing track and update state. Throws on API error so
117	  // callers (the poll loop and the control handlers) can apply their own
118	  // error handling. Both share this so a control action can refresh instantly.
119	  const syncNowPlaying = useCallback(async () => {
120	    const current = await fetchCurrentlyPlaying(token);
121	    if (!mountedRef.current) return;
122	
123	    if (!current) {
124	      devLog("[poll] nothing playing");
125	      setStatus("idle");
126	      return;
127	    }
128	
129	    // update track immediately; location catches up asynchronously
130	    setTrack(current);
131	    setStatus("playing");
132	    devLog(`[poll] now playing: ${current.artistName} – ${current.trackName}`);
133	
134	    if (current.artistName !== lastArtistRef.current) {
135	      lastArtistRef.current = current.artistName;
136	      devLog(`[poll] artist changed, looking up ${current.artistName}`);
137	      const loc = await lookupArtistLocation(current.artistName);
138	      if (mountedRef.current) setLocation(loc ?? UNKNOWN_LOCATION);
139	    }
140	  }, [token]);
141	
142	  // Shared TOKEN_EXPIRED refresh path, guarded so only one refresh runs at a
143	  // time even across overlapping poll/control errors.
144	  const refreshToken = useCallback(async () => {
145	    if (refreshingRef.current) return;
146	    refreshingRef.current = true;
147	    devLog("[poll] token expired, refreshing");
148	    try {
149	      await onTokenExpired();
150	    } finally {
151	      refreshingRef.current = false;
152	    }
153	  }, [onTokenExpired]);
154	
155	  useEffect(() => {
156	    let cancelled = false;
157	
158	    async function poll() {
159	      if (cancelled) return;
160	      try {
161	        await syncNowPlaying();
162	      } catch (err) {
163	        if (cancelled) return;
164	        const action = classifyPollError(err.message);
165	        if (action.type === "refresh") {
166	          await refreshToken();
167	          return;
168	        }
169	        if (action.type === "retry") {
170	          devLog(`[poll] rate limited, retrying in ${action.seconds}s`);
171	          // safe to schedule even near unmount: poll() checks cancelled at the top
172	          setTimeout(poll, action.seconds * 1000);
173	          return;
174	        }
175	        console.error("[poll] error:", err.message);
176	        setStatus("error");
177	      }
178	    }
179	
180	    poll();
181	    const id = setInterval(poll, POLL_MS);
182	    return () => {
183	      cancelled = true;
184	      clearInterval(id);
185	    };
186	  }, [syncNowPlaying, refreshToken]);
187	
188	  async function runControl(action) {
189	    try {
190	      await action();
191	      setControlMessage(null);
192	      return true;
193	    } catch (err) {
194	      if (err.message === "TOKEN_EXPIRED") {
195	        await refreshToken();
196	      } else {
197	        setControlMessage(CONTROL_MESSAGES[err.message] ?? CONTROL_FALLBACK);
198	      }
199	      return false;
200	    }
201	  }
202	
203	  async function handlePlayPause() {
204	    const wasPlaying = track?.isPlaying;
205	    const ok = await runControl(() =>
206	      wasPlaying ? pause(token) : play(token),
207	    );
208	    if (!ok) return;
209	    // Optimistic flip so the icon updates immediately. We deliberately do NOT
210	    // re-sync here: Spotify's currently-playing read is eventually consistent
211	    // and for a moment still reports the old is_playing, which would clobber
212	    // this flip and make the button flicker back. The 5s poll reconciles.
213	    setTrack((t) => (t ? { ...t, isPlaying: !wasPlaying } : t));
214	  }
215	
216	  async function handleNext() {
217	    const ok = await runControl(() => skipToNext(token));
218	    if (!ok) return;
219	    syncNowPlaying().catch(() => {});
220	  }
221	
222	  // Starts playback of the selected library artist. Routes through the
223	  // existing runControl helper (TOKEN_EXPIRED -> refresh, other errors ->
224	  // controlMessage) rather than duplicating that handling here.
225	  // Deliberately does NOT change exploreMode: selecting an artist stays on
226	  // the clustered library view — NowPlayingCard already reflects playback
227	  // regardless of exploreMode, so there's no "switch back" transition.
228	  async function handleSelectArtist(artist) {
229	    await runControl(() =>
230	      play(token, { contextUri: `spotify:artist:${artist.id}` }),
231	    );
232	  }
233	
234	  // "Play something on Spotify" is a prompt for the now-playing view — it's
235	  // the map's empty state. In explore mode the map isn't empty (it's showing
236	  // the clustered library) and the user is deliberately browsing rather than
237	  // listening, so the prompt is just a card floating over content they asked
238	  // for. The error message is kept in both modes: it reports a real failure
239	  // the user should know about, not an empty state.
240	  const statusOverlayMessage =
241	    status === "idle" && !exploreMode
242	      ? "Play something on Spotify"
243	      : status === "error"
244	        ? "Something went wrong. Check the console."
245	        : null;
246	
247	  // NowPlayingCard only exists while a track is actually playing (track can
248	  // go stale — e.g. still set from a previous "playing" poll — once status
249	  // moves to "idle"/"error", so this checks status too, not just track).
250	  // When there's no card to host displayMessage (the scope warning, or a
251	  // transient control error from selecting a library artist while nothing
252	  // is playing), it falls back to its own standalone slot so it's never
253	  // silently dropped just because playback stopped.
254	  const showNowPlayingCard = status === "playing" && track;
255	
256	  return (
257	    <div style={{ position: "relative", height: "100vh", width: "100%" }}>
258	      {/* LeafletMap only gets a track/location while status is actually
259	          "playing" (same condition as showNowPlayingCard) — track/location
260	          state itself is left untouched (syncNowPlaying's artist-change
261	          dedup and handlePlayPause's optimistic flip both still rely on it
262	          persisting across idle/error). Without this, the last-played
263	          AlbumBubble stayed pinned on the map underneath the idle/error
264	          overlay, disagreeing with the (correctly hidden) NowPlayingCard
265	          about whether that track was still current. */}
266	      <LeafletMap
267	        track={showNowPlayingCard ? track : null}
268	        location={showNowPlayingCard ? location : null}
269	        exploreMode={exploreMode}
270	        libraryArtists={artists}
271	        onSelectArtist={handleSelectArtist}
272	      />
273	      {statusOverlayMessage && (
274	        <div style={STATUS_OVERLAY_STYLE}>
275	          <p style={{ margin: 0 }}>{statusOverlayMessage}</p>
276	        </div>
277	      )}
278	      {showNowPlayingCard ? (
279	        <NowPlayingCard
280	          track={track}
281	          placeName={location?.placeName}
282	          onPlayPause={handlePlayPause}
283	          onNext={handleNext}
284	          controlMessage={displayMessage}
285	        />
286	      ) : (
287	        displayMessage && (
288	          <div style={STANDALONE_MESSAGE_STYLE}>{displayMessage}</div>
289	        )
290	      )}
291	      <LibraryLoadingBadge
292	        resolvedCount={resolvedCount}
293	        total={total}
294	        failedCount={failedCount}
295	      />
296	      <BrowseLibraryButton
297	        exploreMode={exploreMode}
298	        onToggle={() => setExploreMode((v) => !v)}
299	      />
300	    </div>
301	  );
302	}
303

