import { render } from "@testing-library/react";
import { MapContainer, TileLayer, useMap } from "react-leaflet";
import { useEffect } from "react";
import { describe, expect, it } from "vitest";

function ClassToggler({ on }) {
  const map = useMap();
  useEffect(() => {
    map.getContainer().classList.toggle("dark-tiles", on);
  }, [on, map]);
  return null;
}

describe("spike", () => {
  it("mounts MapContainer under jsdom and toggles a class via useMap", () => {
    const { container, rerender } = render(
      <MapContainer center={[0, 0]} zoom={2} style={{ height: 200, width: 200 }}>
        <TileLayer url="https://example.com/{z}/{x}/{y}.png" />
        <ClassToggler on={true} />
      </MapContainer>,
    );
    const div = container.querySelector(".leaflet-container");
    expect(div?.classList.contains("dark-tiles")).toBe(true);

    rerender(
      <MapContainer center={[0, 0]} zoom={2} style={{ height: 200, width: 200 }}>
        <TileLayer url="https://example.com/{z}/{x}/{y}.png" />
        <ClassToggler on={false} />
      </MapContainer>,
    );
    expect(div?.classList.contains("dark-tiles")).toBe(false);
  });
});

